INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Betatest?', 2, '[{"text": "Test durch echte Nutzer", "correct": true, "because": "Realistische Bedingungen"}, {"text": "Interne Entwicklerprüfung", "correct": false, "because": "Alphatest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Betatest?', 3, '[{"text": "Fehler vor Veröffentlichung finden", "correct": true, "because": "Qualität sichern"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Betatest?', 5, '[{"text": "Echte Nutzer", "correct": true, "because": "Externer Test"}, {"text": "Realistische Umgebung", "correct": true, "because": "Praxisnah"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Betatest erfolgt vor der Veröffentlichung. b) Er ersetzt den Alphatest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt Alphatest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines Betatests?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Kern des Tests"}, {"text": "Testumgebung", "correct": false, "because": "Realistisch nötig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Betatest nach dem Alphatest stattfindet?', 2, '[{"text": "Ja", "correct": true, "because": "Spätere Phase"}, {"text": "Nein", "correct": false, "because": "Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Betatester?', 3, '[{"text": "Fehler melden", "correct": true, "because": "Nutzerperspektive"}, {"text": "Software programmieren", "correct": false, "because": "Entwickleraufgabe"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung eines Betatests?', 5, '[{"text": "Feedback-Sammlung", "correct": true, "because": "Nutzererfahrungen"}, {"text": "Testplan", "correct": true, "because": "Strukturierte Durchführung"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Betatest findet unter realen Bedingungen statt. b) Er ist nur für Software nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardware möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Betatest unwichtig?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Hauptziel"}, {"text": "Testdauer", "correct": false, "because": "Relevante Planung"}, {"text": "Farbe der Testgeräte", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Betatest öffentlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch geschlossen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Betatest für Fachinformatiker?', 4, '[{"text": "Fehlererkennung", "correct": true, "because": "Realnutzung"}, {"text": "Nutzerakzeptanz", "correct": true, "because": "Feedback vor Release"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Betatest nur Fehler findet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Usability-Feedback"}, {"text": "Ja", "correct": false, "because": "Breiter Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Betatest?', 3, '[{"text": "Nutzerfeedback", "correct": true, "because": "Verbesserungen"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Betatest kann öffentlich sein. b) Er ersetzt interne Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt interne Tests"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechter Betatest?', 5, '[{"text": "Unentdeckte Fehler", "correct": true, "because": "Mangelnde Tiefe"}, {"text": "Negative Nutzererfahrung", "correct": true, "because": "Unzufriedenheit"}, {"text": "Schnellere Veröffentlichung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim Betatest?', 3, '[{"text": "Feedback auswerten", "correct": true, "because": "Verbesserungen umsetzen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betatest automatisiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzerinteraktion nötig"}, {"text": "Ja", "correct": false, "because": "Manuelle Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Betatest-Feedback nutzen?', 4, '[{"text": "JIRA", "correct": true, "because": "Fehlerverfolgung"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
